import os
import glob
import subprocess
import logging

logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(message)s")
logger = logging.getLogger(__name__)

def run_experiments():
    base_dir = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    data_dir = os.path.join(base_dir, "data", "thu_stream_datasets")
    script_path = os.path.join(base_dir, "scripts", "run_dca.py")
    results_base_dir = os.path.join(base_dir, "results_dca_thu_datasets_one_class")
    
    # We look for all *_pre.csv files generated by generate_thu_splits.py
    pre_files = glob.glob(os.path.join(data_dir, "*_pre.csv"))
    datasets = [os.path.basename(f).replace("_pre.csv", "") for f in pre_files]
    
    if not datasets:
        logger.error(f"No datasets found in {data_dir}. Please run generate_thu_splits.py first.")
        return

    logger.info(f"Found {len(datasets)} THU datasets. Starting DCA2 experiments...")
    
    for idx, ds in enumerate(datasets, 1):
        logger.info(f"--- [{idx}/{len(datasets)}] Running DCA on {ds} ---")
        
        # Determine drift type for output subfolder
        if "gradual" in ds:
            results_dir = os.path.join(results_base_dir, "gradual")
        elif "sudden" in ds:
            results_dir = os.path.join(results_base_dir, "sudden")
        else:
            results_dir = os.path.join(results_base_dir, "other")
            
        os.makedirs(results_dir, exist_ok=True)
            
        # Build command invoking run_dca.py
        cmd = [
            "python", script_path,
            "--data_dir", data_dir,
            "--results_dir", results_dir,
            "--dataset", ds,
            "--model", "svc",
            "--by_class"
        ]
        
        try:
            subprocess.run(cmd, check=True)
            logger.info(f"Successfully processed {ds}")
        except subprocess.CalledProcessError as e:
            logger.error(f"Execution failed for {ds}: {e}")

if __name__ == "__main__":
    run_experiments()
